CREATE TABLE `braintogram_mensajes` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `update_id` bigint DEFAULT NULL,
  `tipo` varchar(30) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `chat_id` bigint DEFAULT NULL,
  `chat_type` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `from_id` bigint DEFAULT NULL,
  `from_username` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `from_nombre` varchar(150) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `texto` text COLLATE utf8mb4_general_ci,
  `fecha_telegram` datetime DEFAULT NULL,
  `ip_origen` varchar(45) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `secret_valido` tinyint(1) DEFAULT NULL,
  `chat_autorizado` tinyint(1) DEFAULT NULL,
  `rate_limited` tinyint(1) DEFAULT NULL,
  `raw_json` longtext COLLATE utf8mb4_general_ci,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `update_id` (`update_id`),
  KEY `chat_id` (`chat_id`),
  KEY `created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=78 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
