CREATE TABLE `buscapp_telegrama_destinos` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `telegrama_id` int unsigned NOT NULL,
  `receptor_id` int unsigned NOT NULL,
  `canal` enum('fcm','telegram') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'fcm',
  `estado` enum('enviado','entregado','visto','respondido','anulado_por_despacho','caducado') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'enviado',
  `respuesta` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `entregado_en` datetime DEFAULT NULL,
  `respondido_en` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `telegrama_id` (`telegrama_id`),
  KEY `receptor_id` (`receptor_id`),
  CONSTRAINT `buscapp_telegrama_destinos_receptor_id_foreign` FOREIGN KEY (`receptor_id`) REFERENCES `buscapp_usuarios` (`id`) ON DELETE CASCADE,
  CONSTRAINT `buscapp_telegrama_destinos_telegrama_id_foreign` FOREIGN KEY (`telegrama_id`) REFERENCES `buscapp_telegramas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=71 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
