DROP TABLE IF EXISTS `comidas_alimentos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `comidas_alimentos` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nombre` varchar(180) COLLATE utf8mb4_unicode_ci NOT NULL,
  `marca` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci,
  `es_liquido` tinyint(1) NOT NULL DEFAULT '0',
  `densidad_g_ml` decimal(10,4) DEFAULT NULL,
  `es_receta` tinyint(1) NOT NULL DEFAULT '0',
  `receta_id` bigint unsigned DEFAULT NULL,
  `kcal` decimal(10,2) NOT NULL DEFAULT '0.00',
  `proteina_g` decimal(10,2) NOT NULL DEFAULT '0.00',
  `carbohidratos_g` decimal(10,2) NOT NULL DEFAULT '0.00',
  `azucares_g` decimal(10,2) NOT NULL DEFAULT '0.00',
  `fibra_g` decimal(10,2) NOT NULL DEFAULT '0.00',
  `grasas_g` decimal(10,2) NOT NULL DEFAULT '0.00',
  `grasas_saturadas_g` decimal(10,2) NOT NULL DEFAULT '0.00',
  `omega3_mg` decimal(10,2) NOT NULL DEFAULT '0.00',
  `omega6_mg` decimal(10,2) NOT NULL DEFAULT '0.00',
  `sodio_mg` decimal(10,2) NOT NULL DEFAULT '0.00',
  `calcio_mg` decimal(10,2) NOT NULL DEFAULT '0.00',
  `hierro_mg` decimal(10,2) NOT NULL DEFAULT '0.00',
  `magnesio_mg` decimal(10,2) NOT NULL DEFAULT '0.00',
  `fosforo_mg` decimal(10,2) NOT NULL DEFAULT '0.00',
  `potasio_mg` decimal(10,2) NOT NULL DEFAULT '0.00',
  `zinc_mg` decimal(10,2) NOT NULL DEFAULT '0.00',
  `selenio_ug` decimal(10,2) NOT NULL DEFAULT '0.00',
  `cobre_mg` decimal(10,2) NOT NULL DEFAULT '0.00',
  `manganeso_mg` decimal(10,2) NOT NULL DEFAULT '0.00',
  `yodo_ug` decimal(10,2) NOT NULL DEFAULT '0.00',
  `vitamina_a_rae_ug` decimal(10,2) NOT NULL DEFAULT '0.00',
  `vitamina_c_mg` decimal(10,2) NOT NULL DEFAULT '0.00',
  `vitamina_d_ug` decimal(10,2) NOT NULL DEFAULT '0.00',
  `vitamina_e_mg` decimal(10,2) NOT NULL DEFAULT '0.00',
  `vitamina_k_ug` decimal(10,2) NOT NULL DEFAULT '0.00',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_user_nombre` (`nombre`),
  UNIQUE KEY `uq_alimento_receta` (`receta_id`)
) ENGINE=InnoDB AUTO_INCREMENT=259 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
