  `item_tipo` enum('alimento','receta') COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_id` bigint unsigned NOT NULL,
  `cantidad_gramos` decimal(10,2) DEFAULT NULL,
  `porcion_id` bigint unsigned DEFAULT NULL,
  `porciones` decimal(10,2) DEFAULT NULL,
  `notas` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hora` time DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_dia` (`dia_id`),
  KEY `idx_item` (`item_tipo`,`item_id`),
  KEY `fk_ing_porcion` (`porcion_id`),
  CONSTRAINT `fk_ing_dia` FOREIGN KEY (`dia_id`) REFERENCES `comidas_dias` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ing_porcion` FOREIGN KEY (`porcion_id`) REFERENCES `comidas_alimento_unidades` (`id`) ON DELETE SET NULL
