--
-- Table structure for table `comidas_limites`
--

DROP TABLE IF EXISTS `comidas_limites`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `comidas_limites` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nutriente_id` bigint unsigned NOT NULL,
  `tipo` enum('falta','exceso') COLLATE utf8mb4_unicode_ci NOT NULL,
  `umbral` int NOT NULL,
  `nivel` enum('info','warning','critical') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'warning',
  `mensaje` varchar(140) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_user_nutr_tipo` (`nutriente_id`,`tipo`),
  KEY `idx_lim_nutr` (`nutriente_id`),
  CONSTRAINT `fk_lim_nutr` FOREIGN KEY (`nutriente_id`) REFERENCES `comidas_nutrientes` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

