--
-- Table structure for table `piezas_versiones`
--

DROP TABLE IF EXISTS `piezas_versiones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `piezas_versiones` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `variante_id` int unsigned NOT NULL,
  `numero` smallint unsigned NOT NULL,
  `estado` enum('borrador','impresa','validada','superada','descartada') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'borrador',
  `promocionada_en` datetime DEFAULT NULL,
  `ruta_blend` varchar(500) COLLATE utf8mb4_general_ci NOT NULL,
  `hash_blend` varchar(64) COLLATE utf8mb4_general_ci NOT NULL,
  `cambio` text COLLATE utf8mb4_general_ci NOT NULL,
  `medidas` text COLLATE utf8mb4_general_ci,
  `params_impresion` text COLLATE utf8mb4_general_ci,
  `resultado` text COLLATE utf8mb4_general_ci,
  PRIMARY KEY (`id`),
  UNIQUE KEY `variante_id_numero` (`variante_id`,`numero`),
  CONSTRAINT `piezas_versiones_variante_id_foreign` FOREIGN KEY (`variante_id`) REFERENCES `piezas_variantes` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

