INSERT INTO `piezas_versiones` VALUES (1,1,1,'validada','2026-08-17 04:49:16','variante-1/version-v001.blend','85f5398ad0951942a6cbe4e9a9ac929d12b454e099b188f357d2864bbd77cfd0','Primera versión completa apariencia pincel con cerdas','Grosor mango 3.6mm  y pincel de largo 3cm','1.70s de forma lateral con pico hacia abajo','Perfecta, nítida'),(2,9,1,'descartada','2026-08-17 16:59:09','variante-9/version-v001.blend','b1f420856c3eccabf6a406d762e09103dd3909e0ba90626b89980ff04b60931c','Primer modelado a partir de la fotografía de referencia',NULL,'1.8s, algo de lado','Necesita la base con hueco para no depender de lo plano'),(3,2,1,'validada','2026-08-17 17:04:43','variante-2/version-v001.blend','b525f1c5cb763dd4485a83d21212b04c0caf6c69300cb337458e29f2a821bc80','Primer modelado a partir de la fotografía de referencia',NULL,NULL,'No tiene ningún fallo aparente'),(4,3,1,'validada','2026-08-18 01:01:29','variante-3/version-v001.blend','688e903cd4f7459f0a4665a55122e0d2703abd06b54132e336ccbac79a4f96e1','Viene de una modificación del anterior micrófono','Se mejoró el agarre y la rejilla','Exposición variable','Encaja perfecto en la mano y tiene buen detalle'),(5,7,1,'validada','2026-08-18 04:31:38','variante-7/version-v001.blend','b653757b1597c72b5c5715e366aa3725ac93def70a3a6799e3c063515d7bed68','Primer modelado a partir de la fotografía de referencia',NULL,'exposcion de prueba','Perfecta, quizás demasiado grande.'),(6,11,1,'validada','2026-08-18 04:39:21','variante-11/version-v001.blend','4a8126e9890c1af8a658b15df27060e3afbcaa9ba0ffb9744d233e3faa7c6e92','Primer modelado a partir de la fotografía de referencia',NULL,'1.8s, pistola ligeramente lateral','Perfecta'),(7,4,1,'validada','2026-08-18 04:40:42','variante-4/version-v001.blend','30460345f6b2871bbcbe8f705e3b0ef1253c8f73475ba52ebfe5e46ece190996','Primer modelado a partir de la fotografía de referencia',NULL,'1.8s, mejor inclinarla con las puas arriba y ligeramente inclinada el mango','Ligeramente grande las puas pero bien.'),(8,5,1,'validada','2026-08-18 04:42:31','variante-5/version-v001.blend','86a733e4834c4228eb178b06dc7a7849fabd915aa80e8a5a47f9ef6113d0f196','Primer modelado a partir de la fotografía de referencia',NULL,'1.8s de lado y ligeramente inclinada.','Perfecta y buen agarre'),(9,6,1,'descartada','2026-08-18 04:45:24','variante-6/version-v001.blend','93d4112c24385689cf1064a0f65f9770b1ecc5cf4932201a24a2338156f8c5d5','Primer modelado a partir de la fotografía de referencia',NULL,'1.7s elegir menos soportes, y poner más inclinación quizás de un lateral largo.','Necesita más arco de páginas y el centro más levandado y los bordes más bajos. Más tipo gaviota.'),(10,28,1,'validada','2026-08-18 04:47:00','variante-28/version-v001.blend','cf3b505c69761a88600938c2df8256503c424f8719736721344d3de23ea39b9a','Primer modelado a partir de la fotografía de referencia',NULL,'1.7s impresion con demasiados soportes por defecto\r\n','Perfecta, es más pequeña que la original pero funciona.'),(11,29,1,'validada','2026-08-18 04:47:38','variante-29/version-v001.blend','3b4d1cc39217c52daebc54ec7b2d3c0d4b95365fe85e7df222cc5dea2802f436','Primer modelado a partir de la fotografía de referencia',NULL,'1.7 Puesta de lado para ocupar poco espacio vertical','Perfecto, buen dibujo y medidas.'),(12,30,1,'descartada','2026-08-18 04:49:45','variante-30/version-v001.blend','53b32a7a120e3d18124ae83b07f4f1a08f0a1d7f8487cb6970df5fbbf7c3e9b4','Modelado directamente con IA, enlace en drive',NULL,'1.7s a full de resolucion','Demasiado detalle. Necesita parecer más juguete, ya la versión que está es correcta.'),(13,16,1,'validada','2026-08-18 04:58:40','variante-16/version-v001.blend','0cb1c17d1d8d4d4387652fdd1e5d41f1a344fc7ae5fe9934e99765cf4b7af1f9','Primer modelado a partir de la fotografía de referencia',NULL,'1.8s mano en posición lateral sobre lado más amplio','Perfecta de encaje, algo cerrado pero necesita lijado.'),(14,24,1,'descartada','2026-08-18 05:03:05','variante-24/version-v001.blend','0b19e9754a8511a00e6cc16d809af3626c71b334bbcc8fc17b50d73dec0f97c3','Primer modelado a partir de la fotografía de referencia',NULL,'1.7s mejor soportes detrás del pantalón y ligeramente inclinada','Falla la pared de la pinza que necesita ir un poco más hacia dentro para que el Playmobil quede recto. Atencion a no dejar pequeño el entrepierna.'),(15,15,1,'validada','2026-08-18 05:34:50','variante-15/version-v001.blend','0cb1c17d1d8d4d4387652fdd1e5d41f1a344fc7ae5fe9934e99765cf4b7af1f9','Primer modelado a partir de la fotografía de referencia',NULL,'1.7 versión para añadir el brazo estilo original, poco practico','El riel está perfecto de anchura.'),(16,23,1,'validada','2026-08-18 05:36:48','variante-23/version-v001.blend','d28c29296a63e12773242b716213c92b6a36ea762510a1d31c7be8be27b007e4','Primer modelado a partir de la fotografía de referencia',NULL,'1.7s que mire hacia arriba, si son muchas poner en vertical con cara arriba también','Perfecta, expresión, giro y encaje.'),(17,19,1,'descartada','2026-08-18 05:37:34','variante-19/version-v001.blend','347f0c35a38fe3d53c2b48178b46d351bf097faf95599fc5b14b408ed1f5b23c','Primer modelado a partir de la fotografía de referencia',NULL,'1.7s con el hueco hacia arriba para que los soportes estén en la parte lisa y facil de quitar y lijar','La parte superior quedó pequeña. No se quedan los gorros. Necesita reforzar el interior que se queda frágil una línea nada más.'),(18,18,1,'descartada','2026-08-18 05:41:06','variante-18/version-v001.blend','7948ad4619b85af203b19035cbfcee0fe880a337f0a2972c4bd1700fd2a382be','Primer modelado a partir de la fotografía de referencia',NULL,'1.7s inclinada en los dos ejes en la parte de la pinza los soportes','El modelo impreso no es el corregido, revisar y mirar que esté bien.'),(19,20,1,'descartada','2026-08-18 05:42:56','variante-20/version-v001.blend','8a767ba46521e6614225596394bbd0788f9188141082555b5e11fba3100fb396','Primer modelado a partir de la fotografía de referencia',NULL,'1.7s Inclinada y girada para soportes sobre la espalda','Necesita desde la mitad del agujero de los brazos hacia la cabeza separar hacia afuera el pecho para dejar sitio a la pinza.'),(20,22,1,'validada','2026-08-18 05:51:33','variante-22/version-v001.blend','d28c29296a63e12773242b716213c92b6a36ea762510a1d31c7be8be27b007e4','Primer modelado a partir de la fotografía de referencia',NULL,'1.7s que mire hacia arriba, si son muchas poner en vertical con cara arriba también','Perfecta de encaje, expresión y giro.'),(21,14,1,'descartada','2026-08-18 05:55:24','variante-14/version-v001.blend','044d7df84416d512e98ef512dc164aa9d827304a458998520ad3f5cd0510ad1e','Primer modelado a partir de un brazo normal para probar',NULL,'1.7s sin curar se hace girar la mano. soportes con el brazo entero plano y soportes a lo largo.','Funciona el giro pero las paredes son muy finos. Hay que mejorar el diseño, hacerlo más justo y ampliar las paredes.'),(22,25,1,'validada','2026-08-18 13:08:03','variante-25/version-v001.blend','2a48919db9a4ce55ee0dcfb5ab7d6eb7589018fa70659cfa4d8e6c92b4040a7b','Primera versión con todas las medidas posibles',NULL,'1.7s muchas versiones de altura. En plano para garantizar estabilidad.','Se imprimió bien, con precisión a falta de prueba física si vale en la pistola.'),(23,26,1,'validada','2026-08-18 13:09:26','variante-26/version-v001.blend','c4a809c698b8fc3415fedf737de9276861384574af158f5bb990cb04ee80644a','Primera versión para las piernas dé impresión marcarlas',NULL,'1.7s sin soportes y algunas puedes romperse al despegarse, se juntan a la prueba de impresión bien','Hace su función de pegarse a la muestra de prueba y marcarlas sin que haya confusión'),(24,13,1,'borrador','2026-08-18 13:16:41','variante-13/version-v001.blend','9423a1c8d392ee5f451a0d18df3d2d5f82533213a8b3480926550fbd4ac5b58e','Primera versión con el tamaño corregido',NULL,NULL,NULL),(25,10,1,'borrador','2026-08-18 13:17:20','variante-10/version-v001.blend','6d30b67189ddeecd398ff8a425bed37976ae40c3b945816fa03ead1feeddde51','Primera versión con las medidas corregidas',NULL,NULL,NULL),(26,12,1,'borrador','2026-08-18 13:18:04','variante-12/version-v001.blend','9423a1c8d392ee5f451a0d18df3d2d5f82533213a8b3480926550fbd4ac5b58e','Primera versión con el tamaño corregido',NULL,NULL,NULL),(27,19,2,'borrador','2026-08-18 14:32:59','variante-19/version-v002.blend','81dbf17ae61e7f84f2e6fc407b8a5a697eeaedac9a0ddc12ed19b1cc7a371777','Se modifico la cupula superior, el interior hacia arriba que no hacia falta, y el grosor para entre los gorros.','15,20 mm de diámetro de diadema',NULL,NULL),(31,31,1,'borrador','2026-08-18 15:56:29','variante-31/version-v001.blend','a2040e3f135c22268d59ab0736f9dcd0619dc1ba33130c2f41b4703f1f8c23fc','Primer modelado a partir de la fotografía de referencia',NULL,NULL,NULL),(32,39,1,'borrador','2026-08-18 18:08:15','variante-39/version-v001.blend','3189eee8541b983e9ffebc0cc8cf65f57bfe99837532ba010bf1abfea5087bc1','Primer modelado a partir de la fotografía de referencia',NULL,NULL,NULL),(33,18,2,'borrador','2026-08-19 04:42:59','variante-18/version-v002.blend','9c5b315be88b8e3be48972e03f149435ad96ebba61876423aa862db51c363703','revisión del .blend y corresponde a la nueva versión, se necesita sobreescribir el stl por si no es el correcto',NULL,NULL,NULL),(34,20,2,'borrador','2026-08-19 04:46:37','variante-20/version-v002.blend','df9069bdfb354cb8dfde2699d131d8fddbe15775f6d0b1047dffc25462e3edd0','Se ha modificado las medidas del pecho y la estructura general externa mantiendo el resto. Para hacer sitio a la estructura interior.',NULL,NULL,NULL),(35,24,2,'borrador','2026-08-19 05:12:53','variante-24/version-v002.blend','5f5266772b62d6d3446081d786c2e3b291c13241229cee72d6a117690fe9fd62','Se modifico el hueco de la pinza hacia dentro para que entre y quede recto el muñeco un milimetro, y la entrepierna más notable',NULL,NULL,NULL),(36,9,2,'borrador','2026-08-19 05:55:15','variante-9/version-v002.blend','70c2eeb6954c39a2a4ad7d517ccf2949c1bcb95247137000f526983b50301b81','Se añade el culo hacia dentro para mejorar el acabado y estabilidad',NULL,NULL,NULL),(37,6,2,'borrador','2026-08-19 06:06:08','variante-6/version-v002.blend','7d5b3de72d4f8bc073c7e3d974c40e310817a4a6d825d58bf8cf590acd32e482','Se hace más forma de gaviota, se estiliza los bordes, y se deja que asiente el libro en un plano',NULL,NULL,NULL),(38,30,2,'borrador','2026-08-19 06:26:33','variante-30/version-v002.blend','53b32a7a120e3d18124ae83b07f4f1a08f0a1d7f8487cb6970df5fbbf7c3e9b4','Nuevo modelo STL con la figura reducida de detalle para que parezca más juguete',NULL,NULL,NULL),(39,38,1,'borrador','2026-08-19 15:04:56','variante-38/version-v001.blend','2e33bfca85162b0e36d2b7dee394e32f44e30dc994d98e68e3db32ccc33a4495','Primer modelado a partir de la fotografía de referencia','1.51 de circulo para entrada del pelo.',NULL,NULL),(40,41,1,'borrador','2026-08-19 18:53:34','variante-41/version-v001.blend','31b8f4a166d81df09d268a42f66e4caf0330011ea98e83ababfcb21b134e92e9','Primer modelado a partir de la fotografía de referencia','Ajustado al torso v002 y modelado el tamaño de agarre 3,6mm y el tamaño proporcional a la foto.',NULL,NULL),(41,14,2,'borrador','2026-08-20 01:14:10','variante-14/version-v002.blend','1378285d6f394f64432605e1f2c6f5ecee565b2a02f1e239bdafa9fbb0a01658','Diseño de 3 piezas para probar y ver cual la que realmente funciona mejor con menor a mayor rango de movilidad.',NULL,NULL,NULL);
