--
-- Table structure for table `rodajes_escenas`
--

DROP TABLE IF EXISTS `rodajes_escenas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rodajes_escenas` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `proyecto_id` int unsigned NOT NULL,
  `escena_bloque` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `escena_tomas` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `escena_ubicacion` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `escena_descripcion` text COLLATE utf8mb4_unicode_ci,
  `escena_objetivo` text COLLATE utf8mb4_unicode_ci,
  `escena_accion` text COLLATE utf8mb4_unicode_ci,
  `escena_efecto_especial` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `escena_cont_previa` text COLLATE utf8mb4_unicode_ci,
  `escena_cont_posterior` text COLLATE utf8mb4_unicode_ci,
  `camara_modelo` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `camara_optica` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `camara_apertura` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `camara_fps` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `camara_velocidad` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `camara_iso` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `camara_wb` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `camara_nd` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `camara_tipo_plano` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `camara_angulo` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `camara_movimiento` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `camara_soporte` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `plano_ref_lugar_texto` text COLLATE utf8mb4_unicode_ci,
  `plano_ref_inspiracion_texto` text COLLATE utf8mb4_unicode_ci,
  `plano_esquema_iluminacion` text COLLATE utf8mb4_unicode_ci,
  `plano_hora_dia` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `plano_objetos` text COLLATE utf8mb4_unicode_ci,
  `plano_actores` char(1) COLLATE utf8mb4_unicode_ci DEFAULT 'N',
  `plano_toma_alternativa` text COLLATE utf8mb4_unicode_ci,
  `plano_notas` text COLLATE utf8mb4_unicode_ci,
  `sonido_ambiente` char(1) COLLATE utf8mb4_unicode_ci DEFAULT 'N',
  `sonido_antiviento` char(1) COLLATE utf8mb4_unicode_ci DEFAULT 'N',
  `sonido_dialogo_escrito` text COLLATE utf8mb4_unicode_ci,
  `orden` int unsigned NOT NULL DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_proyecto_id` (`proyecto_id`),
  KEY `idx_orden` (`orden`),
  CONSTRAINT `fk_escena_proyecto` FOREIGN KEY (`proyecto_id`) REFERENCES `rodajes_proyectos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=39 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

